const TOKENS={
  "bg": "#080808",
  "card": "#151515",
  "field": "#252326",
  "line": "#333039",
  "text": "#F7F5FA",
  "muted": "#B4ACBD",
  "purple": "#8C32FF",
  "green": "#76FF03",
  "pink": "#DF43FF",
  "blue": "#4C9BFF",
  "orange": "#FFA21B",
  "yellow": "#F0DF00"
};
// LEVEL UP: native, editable Figma frame importer. No network access or app data.
function rgb(hex){const n=parseInt(hex.slice(1),16);return {r:((n>>16)&255)/255,g:((n>>8)&255)/255,b:(n&255)/255};}
function paint(hex){return [{type:'SOLID',color:rgb(hex)}];}
async function run(){
 const available=await figma.listAvailableFontsAsync();
 const family=['Inter','Roboto','Arial'].find(f=>available.some(x=>x.fontName.family===f))||available[0].fontName.family;
 const options=available.filter(x=>x.fontName.family===family).map(x=>x.fontName);
 const choose=(bold)=>options.find(f=>f.style.replace(/\s/g,'').toLowerCase()===(bold?'semibold':'regular'))||options.find(f=>new RegExp(bold?'bold|medium':'regular|normal','i').test(f.style))||options[0];
 const fonts={400:choose(false),600:choose(true)};
 await Promise.all(Object.values(fonts).map(f=>figma.loadFontAsync(f)));
 const styles={};
 for(const [key,hex]of Object.entries(TOKENS)){const s=figma.createPaintStyle();s.name='LEVEL UP / '+key;s.paints=paint(hex);styles[hex]=s.id;}
 function color(node,hex){node.fills=paint(hex);if(styles[hex])node.fillStyleId=styles[hex];}
 function text(parent,e){const node=figma.createText();parent.appendChild(node);node.name=e.name||e.text.split('\n')[0];node.fontName=fonts[e.weight>=600?600:400];node.fontSize=e.size||14;node.lineHeight={unit:'PERCENT',value:135};node.characters=e.text;node.resize(Math.max(1,e.w),Math.max(1,e.h||24));node.textAutoResize='HEIGHT';node.x=e.x;node.y=e.y;color(node,e.fill||TOKENS.text);return node;}
 const links=[];
 function render(parent,e){
  let node;
  if(e.type==='text')return text(parent,e);
  if(e.type==='rect'){node=figma.createRectangle();parent.appendChild(node);node.name='Card / surface';node.resize(Math.max(1,e.w),Math.max(1,e.h));node.cornerRadius=e.radius||0;color(node,e.fill);if(e.stroke){node.strokes=paint(e.stroke);node.strokeWeight=1;}}
  if(e.type==='icon'){node=figma.createNodeFromSvg(ICONS[e.key]);parent.appendChild(node);node.name='Icon / '+e.key;node.resize(e.w,e.h);}
  if(e.type==='button'){node=figma.createFrame();parent.appendChild(node);node.name='Button / '+e.text;node.resize(e.w,e.h);node.cornerRadius=e.radius||12;node.clipsContent=false;color(node,e.fill);const label=text(node,{x:8,y:0,w:e.w-16,h:24,text:e.text,size:14,weight:600,fill:e.textFill});label.textAlignHorizontal='CENTER';label.y=(e.h-label.height)/2;}
  if(e.type==='hotspot'){node=figma.createFrame();parent.appendChild(node);node.name='Tap target / '+e.destination;node.resize(e.w,e.h);node.fills=[];node.clipsContent=false;}
  if(!node)return;
  node.x=e.x;node.y=e.y;
  if(e.destination)links.push({node,destination:e.destination});
  return node;
 }
 const page=figma.createPage();page.name='LEVEL UP · Complete screen flows';await figma.setCurrentPageAsync(page);
 const sectionNames=[...new Set(SCREENS.map(s=>s.section))],frames=new Map();let nextY=80;
 for(const section of sectionNames){
  text(page,{x:0,y:nextY-48,w:1600,h:32,text:section,size:25,weight:600,fill:'#39313F'});
  const screens=SCREENS.filter(s=>s.section===section);
  for(let i=0;i<screens.length;i++){
   const s=screens[i],frame=figma.createFrame();page.appendChild(frame);frame.name=s.id+' · '+s.name;frame.resize(390,844);frame.x=(i%5)*438;frame.y=nextY+Math.floor(i/5)*915;frame.cornerRadius=24;frame.clipsContent=true;color(frame,TOKENS.bg);frame.setPluginData('screenId',s.id);frame.setPluginData('designNotes',JSON.stringify(s.notes));
   for(const e of s.elements)render(frame,e);frames.set(s.id,frame);
  }
  nextY+=Math.ceil(screens.length/5)*915+105;
 }
 let linked=0;
 for(const {node,destination}of links){const dest=frames.get(destination);if(dest&&typeof node.setReactionsAsync==='function'){try{await node.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:dest.id,navigation:'NAVIGATE',transition:null}]}]);linked++;}catch(error){node.setPluginData('prototypeDestination',destination);}}}
 const library=figma.createPage();library.name='LEVEL UP · Components & tokens';
 text(library,{x:0,y:0,w:1200,h:44,text:'LEVEL UP · Reusable components',size:28,weight:600,fill:'#39313F'});
 const componentSpecs=[
  ['Primary / Workout',[{type:'button',x:0,y:0,w:342,h:48,fill:TOKENS.green,textFill:TOKENS.bg,text:'Continue',radius:12}]],
  ['Primary / Steps',[{type:'button',x:0,y:0,w:342,h:48,fill:TOKENS.purple,textFill:TOKENS.bg,text:'Continue',radius:12}]],
  ['Primary / Nutrition',[{type:'button',x:0,y:0,w:342,h:48,fill:TOKENS.pink,textFill:TOKENS.bg,text:'Continue',radius:12}]],
  ['Input field',[{type:'rect',x:0,y:0,w:342,h:48,fill:TOKENS.field,radius:9},{type:'text',x:12,y:13,w:318,h:23,text:'Input value',size:15,fill:TOKENS.text,weight:400}]],
  ['Card',[{type:'rect',x:0,y:0,w:342,h:120,fill:TOKENS.card,radius:16}]],
  ['Progress track',[{type:'rect',x:0,y:0,w:342,h:6,fill:TOKENS.line,radius:3},{type:'rect',x:0,y:0,w:171,h:6,fill:TOKENS.green,radius:3}]]
 ];
 let cy=95;
 for(const [name,elements]of componentSpecs){text(library,{x:0,y:cy,w:342,h:24,text:name,size:15,weight:600,fill:'#39313F'});const comp=figma.createComponent();library.appendChild(comp);comp.name=name;comp.x=0;comp.y=cy+35;comp.resize(342,Math.max(...elements.map(e=>e.y+e.h)));comp.fills=[];for(const e of elements)render(comp,e);cy+=comp.height+85;}
 let ix=460,iy=95;
 for(const [name,svg]of Object.entries(ICONS)){const component=figma.createComponent();library.appendChild(component);component.name='Icons / '+name;component.resize(64,64);component.x=ix;component.y=iy;component.fills=paint(TOKENS.field);const glyph=figma.createNodeFromSvg(svg);component.appendChild(glyph);glyph.resize(48,48);glyph.x=8;glyph.y=8;ix+=100;if(ix>1000){ix=460;iy+=100;}}
 await figma.setCurrentPageAsync(page);const first=frames.get('today');page.selection=[first];figma.viewport.scrollAndZoomIntoView([first]);
 figma.notify(`Created ${SCREENS.length} editable screens, ${linked} prototype links, and reusable components.`,{timeout:7000});figma.closePlugin();
}
run().catch(error=>{figma.notify('Import stopped: '+String(error),{error:true,timeout:10000});figma.closePlugin();});
